<template>
  <div>

    <!-- TABLE ONLY (NO ACTIONS INSIDE) -->
    <div class="custom-table table3 table-responsive">
      <table class="table">

        <thead>
          <tr>
            <th v-for="chain in approvalRoles" :key="chain?.role_id || chain?.position || chain?.name">
              {{ chain?.role?.name ?? 'no chain' }}
            </th>
          </tr>
        </thead>

        <tbody>
          <tr>
            <td
              v-for="(role, idx) in approvalRoles"
              :key="role?.role_id || idx"
            >
              <span
                v-if="role.status === 'success'"
                class="text text-size"
                :class="getStatusBadgeClass(role.status_name)"
               
              >
                {{ getStatusLabel(role.status_name) }}
              </span>

              <span v-else class="text-secondary  text-size" >
                Pending
              </span>

              <br>

              <span v-if="role?.approved_at" class="small text-muted text-size">
                {{ formatDate(role?.approved_at) }}
              </span>

              <span v-else class="small text-muted text-size">
                ---
              </span>

              <br>

              <span v-if="role?.remark" class="small text-size">
                Remark: {{ role?.remark }}
              </span>
              <span v-else class="small text-muted text-size">
                ---
              </span>

            </td>
          </tr>
        </tbody>

      </table>
    </div>


    <!-- OUTSIDE TABLE: ONLY CURRENT USER ACTION -->
    <div class="mt-3 container text-center" v-for="(role, idx) in approvalRoles" :key="'action-'+idx">

      <div v-if="(role.canAction || user_role == 2) && role.status !== 'success'">

        <div v-if="(role.role_id == 2 && user_role == 2 ) || role.canAction">
       <h5 class="mb-2">
          Action for: {{ role?.role?.name }} 
        </h5>

        <ApprovalActions
          v-model="role.status_id"
          v-model:blockValue="role.block"
          v-model:remarkValue="role.remark"
          :spinner="spinner"
          :loadingSpinner="loadingSpinner"
          :entry-id="props.entry_id"
          @submit="handleApprovalSubmit"
        />
        </div>
 

      </div>

      <!-- ✅ EDIT YOUR OWN APPROVAL (if next role hasn't acted yet) -->
      <div v-if="role.canEditOwn  && role.status === 'success'  ">

        <h5 class="mb-2">
          Edit your approval: {{ role?.role?.name }}
        </h5>

        <ApprovalActions
          v-model="role.status_id"
          v-model:blockValue="role.block"
          v-model:remarkValue="role.remark"
          :spinner="spinner"
          :loadingSpinner="loadingSpinner"
          :entry-id="props.entry_id"
          @submit="handleApprovalSubmit"
        />

      </div>

    </div>

  </div>
</template>

<script setup>
import { inject, ref, watch } from 'vue'
import axios from 'axios'

const axiosInstance = axios.create({
  baseURL: process.env.VUE_APP_API_BASE_URL
})

import ApprovalActions from '../reusables/ApprovalBlock.vue'

const spinner = ref(false)
const showError = inject('showError')
const formatDate = inject('formatDate')
const emit = defineEmits(['loaded', 'submit', 'loading']) 

const user_role = Number(JSON.parse(localStorage.getItem("user"))?.role)
const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;

const entryApproval = ref([])
const approvalRoles = ref([])
const approvalActions = ref([])

const props = defineProps({
  type: [String, Number],
  entry_id: [String, Number]
})

const loadingSpinner = () => {
  return '<span class="spinner-border spinner-border-sm" role="status" aria-hidden="true"></span>'
}

/* ✅ STATUS NAME MAPPING */
const getStatusLabel = (statusName) => {
  const labelMap = {
    'approved': 'Approved',
    'rejected': 'Rejected',
    'remarked': 'Remarked',
    'on_hold': 'On Hold'
  }
  return labelMap[statusName] || 'Unknown'
}

/* ✅ STATUS COLOR MAPPING */
const getStatusBadgeClass = (statusName) => {
  const classMap = {
    'approved': 'text-success',
    'rejected': 'text-danger',
    'remarked': 'text-info',
    'on_hold': 'text-warning '
  }
  return classMap[statusName] || 'text-secondary'
}




const getEntryApproval = async () => {
  emit('loading', true) 
  try {
    const response = await axiosInstance.get(
      `entry-approvals?type_id=${props.type}&entry_id=${props.entry_id}`
    )

    entryApproval.value = response.data

   const roles = response.data?.approval_group?.approval_roles || []

    const actions = response.data?.actions || []

    approvalActions.value = actions

    // STEP 1: map roles with last action
    let mapped = roles.map(roleItem => {

      const matches = actions.filter(action => {
        return String(action?.user?.role) === String(roleItem?.role?.id)
      })

      const lastAction = matches.length
        ? matches.sort((a, b) => new Date(a.created_at) - new Date(b.created_at)).at(-1)
        : null

      return {
        ...roleItem,
        status: lastAction ? 'success' : 'pending',
        status_name: lastAction?.action || null,
        approved_at: lastAction?.created_at || null,
        remark: lastAction?.comment || null
      }
    })

    // STEP 2: find next pending role
    const nextRole = mapped.find(r => r.status !== 'success')
    const nextRoleId = nextRole?.role?.id

    // STEP 3: determine who can act
    // ✅ canAction: It's my turn (next pending role AND I'm that user AND previous role approved)
    // ✅ canEditOwn: I already approved AND the next role hasn't acted yet
mapped = mapped.map((role, currentIdx) => {
  const isMyRole = String(user_role) === String(role.role?.id)
  const isNextPending = role.role?.id === nextRoleId
  const isMyApproval = role.status === 'success' && isMyRole
  const isLastRole = currentIdx === mapped.length - 1          // ✅ NEW
  const nextRoleHasNotActed = mapped[currentIdx + 1]?.status !== 'success'
  const previousRoleApproved = currentIdx === 0 || mapped[currentIdx - 1]?.status_name === 'approved'

  return {
    ...role,
    canAction: isMyRole && isNextPending && previousRoleApproved,
    // ✅ Last role can only edit if their action was NOT 'approved'
    canEditOwn: isMyApproval && (isLastRole ? role.status_name !== 'approved' : nextRoleHasNotActed)
  }
})

    approvalRoles.value = mapped

    emit('loaded', response.data)

  } catch (error) {
    console.log(error)
    showError(error.message)
  }finally{
    emit('loading', false) 
  }
}

const handleApprovalSubmit = (payload) => {
  // console.log('Approval submitted from ApprovalBlock:', payload)
  emit('submit', payload)
}

watch(
  () => [props.type, props.entry_id],
  ([type, entry_id]) => {
    if (!type || !entry_id) return
    getEntryApproval()
  },
  { immediate: true }
)
</script>
<style scoped>
.text-size{
  font-size: 1.1rem;
}
</style>